import {Game,STAGE_COUNT} from './core.js';
export const starsForHealth=(hp,maxHp)=>maxHp>0?(hp/maxHp>=.75?3:hp/maxHp>=2/3?2:hp/maxHp>=.5?1:0):0;
export const emptyProgress=()=>({version:1,challenge:{records:Array(STAGE_COUNT).fill(null),entries:{}},nightmare:{records:Array(STAGE_COUNT).fill(null),entries:{}}});
export function parseStageProgress(raw){const value=typeof raw==='string'?JSON.parse(raw):raw,p=emptyProgress();if(!value||value.version!==1)throw Error('关卡记录无效');for(const mode of ['challenge','nightmare']){const src=value[mode];if(!src||!Array.isArray(src.records)||src.records.length!==STAGE_COUNT||!src.entries||typeof src.entries!=='object')throw Error('关卡记录无效');for(let i=0;i<STAGE_COUNT;i++){const r=src.records[i];if(r!==null){if(!r||!Number.isInteger(r.stars)||r.stars<0||r.stars>3||!Number.isFinite(r.bestRatio)||r.bestRatio<0||r.bestRatio>1||!Number.isInteger(r.clears)||r.clears<1||r.clears>1000000)throw Error('星级记录无效');p[mode].records[i]={stars:r.stars,bestRatio:r.bestRatio,clears:r.clears};}}for(const [key,cp]of Object.entries(src.entries)){const i=Number(key);if(!Number.isInteger(i)||i<0||i>=STAGE_COUNT||cp.stage!==i||cp.mode!==mode)throw Error('关首记录无效');Game.fromCheckpoint(cp);p[mode].entries[i]=cp;}}return p;}
export function recordClear(progress,mode,index,hp,maxHp){const section=progress[mode],stars=starsForHealth(hp,maxHp),ratio=Math.max(0,Math.min(1,hp/maxHp)),old=section.records[index];section.records[index]={stars:Math.max(stars,old?.stars??0),bestRatio:Math.max(ratio,old?.bestRatio??0),clears:(old?.clears??0)+1};return stars;}
export function highestStage(progress,mode){const section=progress[mode];let highest=0;for(let i=0;i<STAGE_COUNT;i++){if(section.entries[i])highest=Math.max(highest,i);if(section.records[i])highest=Math.max(highest,Math.min(STAGE_COUNT-1,i+1));}return highest;}
